import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { Button, Modal, Form, Alert, Spinner } from 'react-bootstrap';
import DataTable from 'react-data-table-component';
import styled from 'styled-components';

const CustomerList = () => {
  // State management
  const [customers, setCustomers] = useState([]);
  const [selectedCustomer, setSelectedCustomer] = useState(null);
  const [showEditModal, setShowEditModal] = useState(false);
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [showDeleteModal, setShowDeleteModal] = useState(false);
  const [customerToDelete, setCustomerToDelete] = useState(null);
  const [newCustomer, setNewCustomer] = useState({
    name: '',
    email: '',
    phone: '',
    location: '',
    address: '',
    postcode: ''
  });
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(true);
  const [searchText, setSearchText] = useState('');
  const [filteredCustomers, setFilteredCustomers] = useState([]);

  // Table columns configuration
  const columns = [
    {
      name: '#',
      selector: (row, index) => index + 1,
      sortable: true,
      width: '70px'
    },
    {
      name: 'Name',
      selector: row => row.name,
      sortable: true,
    },
    {
      name: 'Email',
      selector: row => row.email,
      sortable: true,
    },
    {
      name: 'Phone',
      selector: row => row.phone,
      sortable: true,
    },
    {
      name: 'Location',
      selector: row => row.location,
      sortable: true,
    },
    {
      name: 'Address',
      selector: row => row.address,
      sortable: true,
    },
    {
      name: 'Postcode',
      selector: row => row.postcode,
      sortable: true,
    },
    {
      name: 'Actions',
      cell: (row) => (
        <div>
          <Button 
            variant="outline-primary" 
            size="sm" 
            onClick={() => {
              setSelectedCustomer(row);
              setShowEditModal(true);
            }}
            className="me-2"
          >
            Edit
          </Button>
          <Button 
            variant="outline-danger" 
            size="sm" 
            onClick={() => handleDeleteRequest(row)}
          >
            Delete
          </Button>
        </div>
      ),
      ignoreRowClick: true,
      allowOverflow: true,
      button: true,
    }
  ];

  // Custom styles for DataTable
  const customStyles = {
    headRow: {
      style: {
        backgroundColor: '#343a40',
        color: 'white',
      },
    },
    pagination: {
      style: {
        borderTop: 'none',
      },
    },
  };

  // Fetch customers on mount
  useEffect(() => {
    fetchCustomers();
  }, []);

  // Search filter
  useEffect(() => {
    const filtered = customers.filter(customer =>
      Object.values(customer).some(value =>
        value?.toString().toLowerCase().includes(searchText.toLowerCase())
      )
    );
    setFilteredCustomers(filtered);
  }, [searchText, customers]);

  // API call handlers
  const fetchCustomers = async () => {
    try {
      setLoading(true);
      const response = await axios.get('http://localhost:4567/api/customers');
      setCustomers(response.data);
    } catch (err) {
      setError('Failed to fetch customers');
    } finally {
      setLoading(false);
    }
  };

  const handleCreate = async (e) => {
    e.preventDefault();
    try {
      setLoading(true);
      await axios.post('http://localhost:4567/api/customers', newCustomer);
      setShowCreateModal(false);
      setNewCustomer({ name: '', email: '', phone: '', location: '', address: '', postcode: '' });
      await fetchCustomers();
    } catch (err) {
      setError('Failed to create customer');
    } finally {
      setLoading(false);
    }
  };

  const handleUpdate = async (e) => {
    e.preventDefault();
    try {
      setLoading(true);
      await axios.put(
        `http://localhost:4567/api/customers/${selectedCustomer.id}`,
        selectedCustomer
      );
      setShowEditModal(false);
      await fetchCustomers();
    } catch (err) {
      setError('Failed to update customer');
    } finally {
      setLoading(false);
    }
  };

  const handleDeleteRequest = (customer) => {
    setCustomerToDelete(customer);
    setShowDeleteModal(true);
  };

  const confirmDelete = async () => {
    if (!customerToDelete) return;
    try {
      setLoading(true);
      await axios.delete(`http://localhost:4567/api/customers/${customerToDelete.id}`);
      await fetchCustomers();
    } catch (err) {
      setError('Failed to delete customer');
    } finally {
      setLoading(false);
      setShowDeleteModal(false);
      setCustomerToDelete(null);
    }
  };

  return (
    <div className="container mt-4">
      <div className="d-flex justify-content-between align-items-center mb-4">
        <h1>Customer Management System</h1>
        <Button variant="success" onClick={() => setShowCreateModal(true)}>
          ＋ New Customer
        </Button>
      </div>

      {error && <Alert variant="danger" onClose={() => setError('')} dismissible>{error}</Alert>}

      <div className="card shadow">
        <DataTable
          title="Customers"
          columns={columns}
          data={filteredCustomers}
          progressPending={loading}
          progressComponent={<Spinner animation="border" className="my-4" />}
          pagination
          paginationPerPage={10}
          paginationRowsPerPageOptions={[10, 25, 50, 100]}
          highlightOnHover
          responsive
          subHeader
          subHeaderComponent={
            <input
              type="text"
              placeholder="Search customers..."
              className="form-control"
              value={searchText}
              onChange={(e) => setSearchText(e.target.value)}
              style={{ width: '300px', margin: '10px' }}
            />
          }
          customStyles={customStyles}
          persistTableHead
        />
      </div>

      {/* Create Customer Modal */}
      <Modal show={showCreateModal} onHide={() => setShowCreateModal(false)} size="lg">
        <Modal.Header closeButton>
          <Modal.Title>Create New Customer</Modal.Title>
        </Modal.Header>
        <Form onSubmit={handleCreate}>
          <Modal.Body>
            {loading && <Spinner animation="border" className="mb-3" />}
            <div className="row">
              {/* ... (keep existing create modal content) */}
            </div>
          </Modal.Body>
          <Modal.Footer>
            <Button variant="secondary" onClick={() => setShowCreateModal(false)} disabled={loading}>
              Cancel
            </Button>
            <Button variant="primary" type="submit" disabled={loading}>
              {loading ? 'Creating...' : 'Create Customer'}
            </Button>
          </Modal.Footer>
        </Form>
      </Modal>

      {/* Edit Customer Modal */}
      <Modal show={showEditModal} onHide={() => setShowEditModal(false)} size="lg">
        <Modal.Header closeButton>
          <Modal.Title>Edit Customer Details</Modal.Title>
        </Modal.Header>
        <Form onSubmit={handleUpdate}>
          <Modal.Body>
            {loading ? (
              <Spinner animation="border" className="mb-3" />
            ) : (
              selectedCustomer && (
                <div className="row">
                  {/* ... (keep existing edit modal content) */}
                </div>
              )
            )}
          </Modal.Body>
          <Modal.Footer>
            <Button variant="secondary" onClick={() => setShowEditModal(false)} disabled={loading}>
              Cancel
            </Button>
            <Button variant="primary" type="submit" disabled={loading}>
              {loading ? 'Saving...' : 'Save Changes'}
            </Button>
          </Modal.Footer>
        </Form>
      </Modal>

      {/* Delete Confirmation Modal */}
      <Modal show={showDeleteModal} onHide={() => setShowDeleteModal(false)} centered>
        <Modal.Header closeButton>
          <Modal.Title>Confirm Delete</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          Are you sure you want to delete{' '}
          <strong>{customerToDelete?.name}</strong>?
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={() => setShowDeleteModal(false)} disabled={loading}>
            Cancel
          </Button>
          <Button variant="danger" onClick={confirmDelete} disabled={loading}>
            {loading ? 'Deleting...' : 'Delete'}
          </Button>
        </Modal.Footer>
      </Modal>
    </div>
  );
};

export default CustomerList;
